import type { defineConfig } from 'orval';

/**
 * Generates the typed client and TanStack Query hooks from the OpenAPI spec that
 * the Java API produces (openapi.json, committed, regenerated by the Maven build).
 * Java owns the contract; this package is generated output.
 */
const config: Parameters<typeof defineConfig>[0] = {
  erp: {
    input: './openapi.json',
    output: {
      target: './src/generated/client.ts',
      schemas: './src/generated/model',
      client: 'react-query',
      httpClient: 'fetch',
      mode: 'tags-split',
      baseUrl: '/api',
      clean: true,
      prettier: false,
      override: {
        query: {
          useQuery: true,
          useMutation: true,
        },
        mutator: {
          path: './src/fetcher.ts',
          name: 'apiFetch',
        },
      },
    },
  },
};

export default config;
